try {
  const { keywords, location, jobType, minSalary, _verifyMode } = params;

  // Check for anti-bot on initial page
  await page.checkAntiBot({ maxWait: 10000 });

  // Fill keywords
  await page.waitForSelector('#text-input-what', { timeout: 8000 });
  await page.randomDelay(800, 1500);
  await page.humanType('#text-input-what', keywords || '');
  await page.randomDelay(500, 1000);

  // Fill location
  if (location) {
    await page.humanType('#text-input-where', location);
    await page.randomDelay(500, 1000);
  }

  // Submit search
  await page.humanClick('button[type="submit"].yosegi-InlineWhatWhere-primaryButton');
  await page.waitForNavigation({ timeout: 15000 });
  await page.checkAntiBot({ maxWait: 10000 });
  await page.randomDelay(1500, 2500);

  // Apply job type filter if specified
  if (jobType) {
    const typeMap = {
      'fulltime': 'fulltime',
      'full-time': 'fulltime',
      'parttime': 'parttime',
      'part-time': 'parttime',
      'contract': 'contract',
      'temporary': 'temporary',
      'internship': 'internship'
    };
    const jtKey = typeMap[(jobType || '').toLowerCase()] || jobType.toLowerCase();
    const currentUrl = await page.url();
    const sep = currentUrl.includes('?') ? '&' : '?';
    await page.goto(currentUrl + sep + 'jt=' + jtKey);
    await page.waitForNavigation({ timeout: 15000 }).catch(() => {});
    await page.checkAntiBot({ maxWait: 10000 });
    await page.randomDelay(1500, 2500);
  }

  // Apply salary filter if specified
  if (minSalary) {
    const currentUrl = await page.url();
    const sep = currentUrl.includes('?') ? '&' : '?';
    // Indeed uses salary param like salary=$60,000+ encoded
    await page.goto(currentUrl + sep + 'salary=' + encodeURIComponent(minSalary));
    await page.waitForNavigation({ timeout: 15000 }).catch(() => {});
    await page.checkAntiBot({ maxWait: 10000 });
    await page.randomDelay(1500, 2500);
  }

  // Wait for job cards to load
  await page.waitForSelector('.job_seen_beacon, .jobsearch-ResultsList .result, .mosaic-provider-jobcards .result', { timeout: 10000 }).catch(() => {});
  await page.randomDelay(1000, 2000);

  // Phase 1: Extract job cards
  const jobs = await page.evaluate(() => {
    const results = [];
    const cards = document.querySelectorAll('.job_seen_beacon, .mosaic-zone .result, div[class*="cardOutline"]');

    cards.forEach(card => {
      try {
        const titleEl = card.querySelector('.jcs-JobTitle, a[class*="JobTitle"]');
        const title = titleEl ? titleEl.textContent.trim() : '';

        let url = '';
        if (titleEl) {
          const link = titleEl.tagName === 'A' ? titleEl : titleEl.closest('a');
          if (link) {
            const rawHref = link.href || '';
            // Prefer the real href; extract jk param for a clean canonical URL
            if (rawHref) {
              try {
                const parsedUrl = new URL(rawHref, 'https://ca.indeed.com');
                const jkParam = parsedUrl.searchParams.get('jk');
                url = jkParam ? 'https://ca.indeed.com/viewjob?jk=' + jkParam : rawHref;
              } catch(e) {
                url = rawHref;
              }
            } else if (link.id) {
              // Fallback: reconstruct from element id (sj_xxxx format)
              const jk = link.id.replace(/^sj_/, '');
              if (jk) url = 'https://ca.indeed.com/viewjob?jk=' + jk;
            }
          }
        }

        const companyEl = card.querySelector('[data-testid="company-name"], .companyName, .company_location .companyName, span[class*="company"]');
        const company = companyEl ? companyEl.textContent.trim() : '';

        const locationEl = card.querySelector('[data-testid="text-location"], .companyLocation, div[class*="company_location"] div[data-testid="text-location"]');
        const loc = locationEl ? locationEl.textContent.trim() : '';

        const salaryEl = card.querySelector('.salary-snippet-container, div[class*="salary"], .metadata.salary-snippet-container, [class*="SalarySnippet"], div[class*="salaryOnly"]');
        const salary = salaryEl ? salaryEl.textContent.trim() : '';

        const snippetEl = card.querySelector('.job-snippet, td.snip .job-snippet, [class*="JobSnippet"], ul[style]');
        const description = snippetEl ? snippetEl.textContent.trim() : '';

        if (title) {
          results.push({
            title,
            company,
            url,
            location: loc,
            salary,
            description,
            fullText: ''
          });
        }
      } catch (e) {
        // skip bad card
      }
    });

    return results;
  });

  // Phase 2: JD Detail Extraction
  if (_verifyMode) {
    jobs.forEach(j => { j.fullText = ''; });
  } else {
    for (let i = 0; i < jobs.length; i++) {
      try {
        // Click the job card title to open split-pane detail
        const titleSelectors = '.jcs-JobTitle, a[class*="JobTitle"]';
        const allTitles = await page.$$(titleSelectors);
        if (allTitles && allTitles.length > i) {
          const sel = typeof allTitles[i] === 'string' ? allTitles[i] : titleSelectors + `:nth-of-type(${i + 1})`;
          // Use evaluate to click the i-th title
          await page.evaluate((idx) => {
            const titles = document.querySelectorAll('.jcs-JobTitle, a[class*="JobTitle"]');
            if (titles[idx]) titles[idx].click();
          }, i);

          await page.randomDelay(1500, 3000);

          // Extract full job description from the detail panel
          const fullText = await page.evaluate(() => {
            const selectors = [
              '#jobDescriptionText',
              '.jobsearch-JobComponent-description',
              '[class*="jobDescription"]',
              '.jobsearch-jobDescriptionText',
              '#jobDescriptionText .jobsearch-JobComponent-description'
            ];
            for (const sel of selectors) {
              const el = document.querySelector(sel);
              if (el && el.textContent.trim().length > 50) {
                return el.textContent.trim();
              }
            }
            // Fallback: try the right pane
            const rightPane = document.querySelector('.jobsearch-RightPane, [class*="RightPane"], .jobsearch-ViewJobLayout--inline');
            if (rightPane) return rightPane.textContent.trim();
            return '';
          });

          jobs[i].fullText = fullText || '';
        }
      } catch (e) {
        jobs[i].fullText = '';
      }
    }
  }

  return { success: true, jobs };

} catch (error) {
  return { success: false, error: error.message || String(error) };
}

try {
  // Phase 0: Build search URL and navigate directly
  const baseUrl = 'https://www.linkedin.com/jobs/search/?';
  const searchParams = new URLSearchParams();

  if (params.keywords) searchParams.set('keywords', params.keywords);
  if (params.location) searchParams.set('location', params.location);

  // jobType mapping: F=Full-time, P=Part-time, C=Contract, T=Temporary, I=Internship
  if (params.jobType) {
    const jobTypeMap = {
      'full-time': 'F', 'fulltime': 'F', 'F': 'F',
      'part-time': 'P', 'parttime': 'P', 'P': 'P',
      'contract': 'C', 'C': 'C',
      'temporary': 'T', 'T': 'T',
      'internship': 'I', 'I': 'I'
    };
    const mapped = jobTypeMap[params.jobType] || params.jobType;
    searchParams.set('f_JT', mapped);
  }

  // Salary filter (LinkedIn uses f_SB2 for salary ranges)
  if (params.minSalary) {
    // LinkedIn salary buckets: 1=$40k+, 2=$60k+, 3=$80k+, 4=$100k+, 5=$120k+, 6=$140k+, 7=$160k+, 8=$180k+, 9=$200k+
    const salary = parseInt(params.minSalary);
    let salaryBucket = '';
    if (salary >= 200000) salaryBucket = '9';
    else if (salary >= 180000) salaryBucket = '8';
    else if (salary >= 160000) salaryBucket = '7';
    else if (salary >= 140000) salaryBucket = '6';
    else if (salary >= 120000) salaryBucket = '5';
    else if (salary >= 100000) salaryBucket = '4';
    else if (salary >= 80000) salaryBucket = '3';
    else if (salary >= 60000) salaryBucket = '2';
    else if (salary >= 40000) salaryBucket = '1';
    if (salaryBucket) searchParams.set('f_SB2', salaryBucket);
  }

  searchParams.set('origin', 'JOBS_HOME_SEARCH_BUTTON');

  const searchUrl = baseUrl + searchParams.toString();
  await page.goto(searchUrl);
  await page.randomDelay(2000, 3500);
  await page.checkAntiBot({ maxWait: 10000 });

  // Wait for job results to load - try multiple possible selectors
  const jobListSelectors = [
    '.jobs-search-results-list',
    '.jobs-search__results-list',
    '[class*="jobs-search-results"]',
    '.scaffold-layout__list',
    'ul.scaffold-layout__list-container',
    '[class*="scaffold-layout__list"]'
  ];

  let listFound = false;
  for (const sel of jobListSelectors) {
    try {
      await page.waitForSelector(sel, { timeout: 6000 });
      listFound = true;
      break;
    } catch (e) {
      // try next selector
    }
  }

  if (!listFound) {
    // Fallback: try typing in the search fields on the current page
    const keywordInput = await page.$('input[id=":r1:"]') 
      || await page.$('input[placeholder*="Title"]')
      || await page.$('input[placeholder*="skill"]')
      || await page.$('[data-testid="typeahead-input"]');

    if (keywordInput && params.keywords) {
      await page.humanClick(keywordInput);
      await page.randomDelay(500, 1000);
      await page.humanType(keywordInput, params.keywords);
      await page.randomDelay(800, 1500);
      await page.keyboard.press('Enter');
      await page.randomDelay(3000, 5000);
      await page.checkAntiBot({ maxWait: 10000 });
    }

    // Try waiting again after manual search
    for (const sel of jobListSelectors) {
      try {
        await page.waitForSelector(sel, { timeout: 8000 });
        listFound = true;
        break;
      } catch (e) {
        // try next
      }
    }
  }

  // Wait a bit more for cards to render
  await page.randomDelay(2000, 3000);

  // Scroll down to load more job cards (LinkedIn lazy-loads)
  const maxScrolls = 5;
  for (let scrollIdx = 0; scrollIdx < maxScrolls; scrollIdx++) {
    const prevCount = await page.evaluate(() => {
      return document.querySelectorAll('[data-occludable-job-id], .scaffold-layout__list-container > li, a[href*="/jobs/view/"]').length;
    });

    // Scroll the job list container
    await page.evaluate(() => {
      const listContainer = document.querySelector('.jobs-search-results-list, .scaffold-layout__list, [class*="jobs-search-results"]');
      if (listContainer) {
        listContainer.scrollTop = listContainer.scrollHeight;
      } else {
        window.scrollTo(0, document.body.scrollHeight);
      }
    });
    await page.randomDelay(1500, 2500);

    const newCount = await page.evaluate(() => {
      return document.querySelectorAll('[data-occludable-job-id], .scaffold-layout__list-container > li, a[href*="/jobs/view/"]').length;
    });

    // Stop scrolling if no new cards loaded or we have enough
    if (newCount <= prevCount || newCount >= (params.maxResults || 30)) break;
  }
  await page.randomDelay(1000, 2000);

  // Phase 1: Extract job cards
  const jobs = await page.evaluate(() => {
    const results = [];

    // Strategy 1: Look for job card list items with data-occludable-job-id
    let cards = document.querySelectorAll('[data-occludable-job-id]');

    // Strategy 2: Look for li elements inside the scaffold list
    if (!cards.length) {
      cards = document.querySelectorAll('.scaffold-layout__list-container > li');
    }

    // Strategy 3: Look for job card containers
    if (!cards.length) {
      cards = document.querySelectorAll('[class*="job-card-container"]');
    }

    // Strategy 4: Look for any li with job card links
    if (!cards.length) {
      cards = document.querySelectorAll('li[class*="jobs-search"]');
    }

    // Strategy 5: Broad search for job card anchors
    if (!cards.length) {
      const anchors = document.querySelectorAll('a[href*="/jobs/view/"]');
      anchors.forEach(a => {
        const card = a.closest('li') || a.parentElement;
        if (card) {
          const title = a.textContent.trim().split('\n')[0].trim();
          const href = a.href;
          // Try to find company, location from siblings/parent
          const allText = card.textContent.trim();
          const lines = allText.split('\n').map(l => l.trim()).filter(Boolean);

          results.push({
            title: title || lines[0] || '',
            company: lines[1] || '',
            url: href,
            location: lines[2] || '',
            salary: '',
            description: lines.slice(3).join(' ').substring(0, 300),
            fullText: ''
          });
        }
      });
      return results;
    }

    cards.forEach(card => {
      try {
        // Find the main job link
        const link = card.querySelector('a[href*="/jobs/view/"]') 
          || card.querySelector('a[class*="job-card"]')
          || card.querySelector('a');

        if (!link) return;

        const url = link.href || '';

        // Title: usually in a strong, span, or the link text itself
        const titleEl = card.querySelector('[class*="job-card-list__title"]')
          || card.querySelector('a[class*="job-card"] strong')
          || card.querySelector('[class*="artdeco-entity-lockup__title"] strong')
          || card.querySelector('strong')
          || link;
        const title = (titleEl ? titleEl.textContent : '').trim().split('\n')[0].trim();

        // Company
        const companyEl = card.querySelector('[class*="artdeco-entity-lockup__subtitle"]')
          || card.querySelector('[class*="job-card-container__primary-description"]')
          || card.querySelector('[class*="company"]');
        const company = (companyEl ? companyEl.textContent : '').trim().split('\n')[0].trim();

        // Location
        const locationEl = card.querySelector('[class*="artdeco-entity-lockup__caption"]')
          || card.querySelector('[class*="job-card-container__metadata-item"]')
          || card.querySelector('[class*="location"]');
        const location = (locationEl ? locationEl.textContent : '').trim().split('\n')[0].trim();

        // Salary (if shown)
        const salaryEl = card.querySelector('[class*="salary"]')
          || card.querySelector('[class*="compensation"]');
        const salary = (salaryEl ? salaryEl.textContent : '').trim();

        // Description snippet
        const descEl = card.querySelector('[class*="job-card-list__footer"]')
          || card.querySelector('[class*="job-card-container__footer"]');
        const description = (descEl ? descEl.textContent : '').trim().substring(0, 300);

        if (title || url) {
          results.push({ title, company, url, location, salary, description, fullText: '' });
        }
      } catch (e) {
        // skip bad card
      }
    });

    return results;
  });

  // Deduplicate by URL
  const seen = new Set();
  const uniqueJobs = jobs.filter(j => {
    if (!j.url || seen.has(j.url)) return false;
    seen.add(j.url);
    return true;
  });

  // Phase 2: JD Detail Extraction
  if (params._verifyMode) {
    uniqueJobs.forEach(j => { j.fullText = ''; });
  } else {
    // Click each job card to load details in the split pane
    for (let i = 0; i < uniqueJobs.length; i++) {
      try {
        const job = uniqueJobs[i];

        // Find and click the job card link
        const clicked = await page.evaluate((jobUrl) => {
          const links = document.querySelectorAll('a[href*="/jobs/view/"]');
          for (const link of links) {
            if (link.href === jobUrl || link.href.includes(jobUrl.split('/jobs/view/')[1]?.split('?')[0])) {
              // Scroll into view
              link.scrollIntoView({ behavior: 'smooth', block: 'center' });
              return true;
            }
          }
          return false;
        }, job.url);

        if (clicked) {
          // Use humanClick on the matching link
          try {
            const jobIdMatch = job.url.match(/\/jobs\/view\/(\d+)/);
            const jobId = jobIdMatch ? jobIdMatch[1] : null;

            let selector = `a[href*="/jobs/view/${jobId}"]`;
            if (!jobId) {
              selector = `a[href="${job.url}"]`;
            }

            await page.humanClick(selector);
          } catch (clickErr) {
            // Fallback: evaluate click
            await page.evaluate((jobUrl) => {
              const links = document.querySelectorAll('a[href*="/jobs/view/"]');
              for (const link of links) {
                if (link.href.includes(jobUrl.split('/jobs/view/')[1]?.split('?')[0] || '___')) {
                  link.click();
                  return;
                }
              }
            }, job.url);
          }

          await page.randomDelay(1500, 3000);

          // Extract full JD from the detail panel
          const fullText = await page.evaluate(() => {
            // LinkedIn job detail selectors (split-pane right side)
            const selectors = [
              '#job-details',
              '.jobs-description__content',
              '.jobs-description-content__text',
              '[class*="jobs-description"]',
              '.jobs-box__html-content',
              '[class*="job-details"]',
              '.jobs-unified-top-card',
              '[class*="jobs-unified"]'
            ];

            for (const sel of selectors) {
              const el = document.querySelector(sel);
              if (el && el.textContent.trim().length > 50) {
                return el.textContent.trim();
              }
            }

            // Fallback: get the right panel content
            const rightPanel = document.querySelector('.jobs-search__job-details')
              || document.querySelector('[class*="job-details-module"]')
              || document.querySelector('.scaffold-layout__detail');

            if (rightPanel) {
              return rightPanel.textContent.trim().substring(0, 5000);
            }

            return '';
          });

          job.fullText = fullText || '';
        } else {
          job.fullText = '';
        }
      } catch (detailErr) {
        uniqueJobs[i].fullText = '';
      }
    }
  }

  return { success: true, jobs: uniqueJobs };

} catch (error) {
  return { success: false, error: error.message || String(error) };
}
